:root {
  --bg: #ffffff;
  --border: #e4e0d8;
  --header-bg: #2c2416;
  --header-text: #f5efe4;
  --label-color: #a8916a;
  --title-color: #f5efe4;
  --ring-bg: #3e3020;
  --ring-border: #c4894a;
  --ring-value: #f0c97a;
  --ring-sub: #a8916a;
  --task-bg: #faf8f4;
  --task-border: #ede8de;
  --task-done-icon: #7aab6e;
  --task-done-name: #7a7060;
  --task-active-bg: #fff8ec;
  --task-active-border: #c4894a;
  --task-active-icon: #c4894a;
  --task-active-name: #2c2416;
  --task-pending-icon: #c8bfae;
  --task-pending-name: #a09080;
  --task-date: #b0a090;
  --footer-bg: #faf8f4;
  --stat-value: #2c2416;
  --stat-label: #a09080;
  --divider-color: #ede8de;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.tracker {
  width: 480px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
}

.tracker-header {
  background: var(--header-bg);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--label-color);
  text-transform: uppercase;
}

.project-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  color: var(--title-color);
  line-height: 1.2;
}

.progress-ring {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--ring-bg);
  border: 3px solid var(--ring-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0px;
}

.ring-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--ring-value);
  line-height: 1.1;
}

.ring-sub {
  font-size: 10px;
  font-weight: 500;
  color: var(--ring-sub);
}

.tasks {
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.task {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  background: var(--task-bg);
  border: 1px solid var(--task-border);
}

.task--active {
  background: var(--task-active-bg);
  border: 1px solid var(--task-active-border);
}

.task-icon {
  font-size: 14px;
  width: 18px;
  text-align: center;
  flex-shrink: 0;
}

.task--done .task-icon {
  color: var(--task-done-icon);
}

.task--active .task-icon {
  color: var(--task-active-icon);
}

.task--pending .task-icon {
  color: var(--task-pending-icon);
}

.task-name {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
}

.task--done .task-name {
  color: var(--task-done-name);
  text-decoration: line-through;
}

.task--active .task-name {
  color: var(--task-active-name);
  font-weight: 700;
}

.task--pending .task-name {
  color: var(--task-pending-name);
}

.task-date {
  font-size: 11px;
  font-weight: 500;
  color: var(--task-date);
}

.tracker-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--border);
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--stat-value);
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  font-weight: 500;
  color: var(--stat-label);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.divider {
  width: 1px;
  height: 32px;
  background: var(--divider-color);
}
